import { useState, useCallback, useEffect } from "react";
import type { PartialValidationRules, UseFormReturn, ValidationLifecycleConfig, FormLevelValidation, ValidationState, SubmitLifecycle, SubmitContext } from "../types";

export function useForm<T extends Record<string, any>>(
    initialValues: T,
    validationRules?: PartialValidationRules<T>,
    validationLifecycle?: ValidationLifecycleConfig,
    formLevelValidation?: FormLevelValidation<T>,
    submitLifecycle?: SubmitLifecycle<T>
) {
    const [values, setValues] = useState<T>(initialValues);
    const [errors, setErrors] = useState<Partial<Record<keyof T, string>>>({});
    const [touched, setTouched] = useState<Partial<Record<keyof T, boolean>>>({});
    const [dirty, setDirty] = useState<Partial<Record<keyof T, boolean>>>({});
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [isValid, setIsValid] = useState(true);
    const [canSubmit, setCanSubmit] = useState(true);
    const [isDirty, setIsDirty] = useState(false);
    const [isComplete, setIsComplete] = useState(false);
    const [submitCount, setSubmitCount] = useState(0);
    const [submitError, setSubmitError] = useState<string | undefined>();
    const [formError, setFormError] = useState<string | undefined>();
    const [validationState, setValidationState] = useState<ValidationState>({
        validating: false,
        validatedFields: new Set(),
        asyncErrors: {}
    });

    const validateField = useCallback(<K extends keyof T>(field: K, value: T[K]): string | undefined => {
        const rules = validationRules?.[field];
        if (!rules) return undefined;

        if (rules.required && (!value || value === '')) {
            return rules.message || `${String(field)} is required`;
        }

        if (typeof value === 'string') {
            if (rules.min && value.length < rules.min) {
                return rules.message || `${String(field)} must be at least ${rules.min} characters`;
            }
            if (rules.max && value.length > rules.max) {
                return rules.message || `${String(field)} must be no more than ${rules.max} characters`;
            }
            if (rules.pattern && !rules.pattern.test(value)) {
                return rules.message || `${String(field)} format is invalid`;
            }
        }

        if (typeof value === 'number') {
            if (rules.min !== undefined && value < rules.min) {
                return rules.message || `${String(field)} must be at least ${rules.min}`;
            }
            if (rules.max !== undefined && value > rules.max) {
                return rules.message || `${String(field)} must be no more than ${rules.max}`;
            }
        }

        if (rules.custom) {
            return rules.custom(value, values);
        }

        if (rules.crossField) {
            return rules.crossField(value, values);
        }

        return undefined;
    }, [validationRules, values]);

    const validateAll = useCallback(async (): Promise<boolean> => {
        const newErrors: Partial<Record<keyof T, string>> = {};
        let isValid = true;

        // Field-level validation
        Object.keys(values).forEach((key) => {
            const field = key as keyof T;
            const error = validateField(field, values[field]);
            if (error) {
                newErrors[field] = error;
                isValid = false;
            }
        });

        // Form-level validation
        if (formLevelValidation?.validate) {
            const formError = formLevelValidation.validate(values);
            if (formError) {
                setFormError(formError);
                isValid = false;
            } else {
                setFormError(undefined);
            }
        }

        setErrors(newErrors);
        return isValid;
    }, [values, validateField, formLevelValidation]);

    const validateFieldAsync = useCallback(async <K extends keyof T>(field: K, value: T[K]): Promise<string | undefined> => {
        const rules = validationRules?.[field];
        if (!rules?.async) return undefined;

        setValidationState(prev => ({
            ...prev,
            validating: true,
            validatedFields: new Set([...prev.validatedFields, String(field)])
        }));

        try {
            const error = await rules.async(value, values);
            setValidationState(prev => ({
                ...prev,
                validating: false,
                asyncErrors: {
                    ...prev.asyncErrors,
                    [field]: error || undefined
                }
            }));
            return error;
        } catch (err) {
            setValidationState(prev => ({
                ...prev,
                validating: false,
                asyncErrors: {
                    ...prev.asyncErrors,
                    [field]: 'Validation error occurred'
                }
            }));
            return 'Validation error occurred';
        }
    }, [validationRules, values]);

    const validateAllAsync = useCallback(async (): Promise<boolean> => {
        setValidationState(prev => ({ ...prev, validating: true }));
        
        const newErrors: Partial<Record<keyof T, string>> = {};
        const asyncErrors: Record<string, string> = {};
        let isValid = true;

        // Run sync validation first
        Object.keys(values).forEach((key) => {
            const field = key as keyof T;
            const error = validateField(field, values[field]);
            if (error) {
                newErrors[field] = error;
                isValid = false;
            }
        });

        // Run async validation in parallel
        const asyncValidationPromises = Object.keys(values).map(async (key) => {
            const field = key as keyof T;
            const rules = validationRules?.[field];
            if (rules?.async) {
                try {
                    const error = await rules.async(values[field], values);
                    if (error) {
                        asyncErrors[String(field)] = error;
                        isValid = false;
                    }
                } catch (err) {
                    asyncErrors[String(field)] = 'Validation error occurred';
                    isValid = false;
                }
            }
        });

        await Promise.all(asyncValidationPromises);

        // Form-level async validation
        if (formLevelValidation?.async) {
            try {
                const formError = await formLevelValidation.async(values);
                if (formError) {
                    setFormError(formError);
                    isValid = false;
                } else {
                    setFormError(undefined);
                }
            } catch (err) {
                setFormError('Form validation error occurred');
                isValid = false;
            }
        }

        setErrors({ ...newErrors, ...asyncErrors });
        setValidationState({
            validating: false,
            validatedFields: new Set(Object.keys(values)),
            asyncErrors
        });

        return isValid;
    }, [values, validateField, validationRules, formLevelValidation]);

    const handleChange = useCallback(
        (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
            const { name, value, type } = e.target;
            const checked = (e.target as HTMLInputElement).checked;

            const field = name as keyof T;
            
            let fieldValue: T[keyof T];
            
            if (type === "checkbox") {
                fieldValue = checked as T[keyof T];
            } else if (type === "number") {
                fieldValue = (parseInt(value, 10) || 0) as T[keyof T];
            } else {
                fieldValue = value as T[keyof T];
            }

            setValues((prev) => ({ ...prev, [field]: fieldValue }));
            
            // Track dirty state for individual fields
            setDirty((prev) => ({ ...prev, [field]: fieldValue !== initialValues[field] }));
            
            // Smart validation logic based on lifecycle configuration
            const shouldValidateOnChange = validationLifecycle?.validateOnChange;
            const shouldShowErrorsAfterTouched = validationLifecycle?.showErrorsAfterTouched !== false;
            const shouldShowErrorsAfterSubmit = validationLifecycle?.showErrorsAfterSubmit !== false;
            const hasBeenSubmitted = submitCount > 0;
            const fieldIsTouched = touched[field];
            
            // Validate on change if:
            // 1. validateOnChange is explicitly true, OR
            // 2. Field has been touched and showErrorsAfterTouched is true, OR
            // 3. Form has been submitted and showErrorsAfterSubmit is true
            if (shouldValidateOnChange || 
                (fieldIsTouched && shouldShowErrorsAfterTouched) || 
                (hasBeenSubmitted && shouldShowErrorsAfterSubmit)) {
                const error = validateField(field, fieldValue);
                setErrors((prev) => ({ ...prev, [field]: error }));
            }
        },
        [touched, validateField, validationLifecycle, initialValues, submitCount]
    );

    const handleBlur = useCallback(
        (e: React.FocusEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
            const { name } = e.target;
            const field = name as keyof T;
            
            setTouched((prev) => ({ ...prev, [field]: true }));
            
            // Smart validation logic for blur events
            const shouldValidateOnBlur = validationLifecycle?.validateOnBlur !== false;
            const shouldShowErrorsAfterTouched = validationLifecycle?.showErrorsAfterTouched !== false;
            const shouldShowErrorsAfterSubmit = validationLifecycle?.showErrorsAfterSubmit !== false;
            const hasBeenSubmitted = submitCount > 0;
            
            // Validate on blur if:
            // 1. validateOnBlur is not explicitly false, AND
            // 2. Either showErrorsAfterTouched is true (default) OR form has been submitted and showErrorsAfterSubmit is true
            if (shouldValidateOnBlur && 
                (shouldShowErrorsAfterTouched || (hasBeenSubmitted && shouldShowErrorsAfterSubmit))) {
                const error = validateField(field, values[field]);
                setErrors((prev) => ({ ...prev, [field]: error }));
            }
        },
        [values, validateField, validationLifecycle, submitCount]
    );

    const setField = useCallback(<K extends keyof T>(field: K, value: T[K]) => {
        setValues((prev: T) => ({ ...prev, [field]: value }));
        
        // Track dirty state for individual fields
        setDirty((prev) => ({ ...prev, [field]: value !== initialValues[field] }));
        
        // Validate based on configuration and touched state
        if ((validationLifecycle?.validateOnChange) || touched[field]) {
            const error = validateField(field, value);
            setErrors((prev) => ({ ...prev, [field]: error }));
        }
    }, [touched, validateField, validationLifecycle, initialValues]);

    const setFieldError = useCallback(<K extends keyof T>(field: K, error?: string) => {
        setErrors((prev) => ({ ...prev, [field]: error }));
    }, []);

    const setErrorsCallback = useCallback((newErrors: Partial<Record<keyof T, string>>) => {
        setErrors(newErrors);
    }, []);

    const setSubmitting = useCallback((submitting: boolean) => {
        setIsSubmitting(submitting);
        if (submitting) {
            setSubmitError(undefined); // Clear submit error when starting submission
        }
    }, []);

    const setSubmitErrorCallback = useCallback((error?: string) => {
        setSubmitError(error);
    }, []);

    const reset = useCallback(() => {
        setValues(initialValues);
        setErrors({});
        setTouched({});
        setDirty({});
        setIsSubmitting(false);
        setSubmitCount(0);
        setSubmitError(undefined);
        setFormError(undefined);
        setValidationState({
            validating: false,
            validatedFields: new Set(),
            asyncErrors: {}
        });
    }, [initialValues]);

    // Update computed state flags whenever values, errors, or touched change
    useEffect(() => {
        const hasErrors = Object.keys(errors).some(key => errors[key as keyof T]);
        const hasFormError = !!formError;
        const isCurrentlyValidating = validationState.validating;
        const hasSubmitError = !!submitError;
        
        const allValid = !hasErrors && !hasFormError && !isCurrentlyValidating;
        setIsValid(allValid);
        
        // Automatic submit guard: canSubmit when form is valid, dirty, complete, not validating, and not submitting
        const canSubmit = allValid && isDirty && isComplete && !isCurrentlyValidating && !isSubmitting;
        setCanSubmit(canSubmit);
        
        // dirty when any field value differs from initialValues
        const dirty = Object.keys(values).some((key) => {
            const k = key as keyof T;
            return values[k] !== initialValues[k];
        });
        setIsDirty(dirty);
        
        // complete when all fields have a value (including false for booleans)
        const complete = Object.keys(values).every((key) => {
            const k = key as keyof T;
            const val = values[k];
            return val !== undefined && val !== null && val !== '';
        });
        setIsComplete(complete);
    }, [values, errors, formError, submitError, validationState.validating, isSubmitting, initialValues, isDirty]);

    const handleSubmit = useCallback(
        (onSubmit: (context: SubmitContext<T>) => void | Promise<void>) => {
            return async (e: React.FormEvent) => {
                e.preventDefault();
                
                // Automatic submit guard - prevent submission if form is not ready
                if (!canSubmit || isSubmitting) {
                    return;
                }
                
                setIsSubmitting(true);
                setSubmitCount(prev => prev + 1);
                setSubmitError(undefined); // Clear previous submit error
                
                let isValid = true;
                let submissionSuccess = false;
                
                try {
                    // Call onSubmitStart hook
                    if (submitLifecycle?.onSubmitStart) {
                        await submitLifecycle.onSubmitStart(values);
                    }
                    
                    // Validate on submit based on configuration (default to true)
                    if (validationLifecycle?.validateOnSubmit !== false) {
                        isValid = await validateAll();
                    }
                    
                    if (isValid) {
                        // Create submit context with form helpers
                        const context: SubmitContext<T> = {
                            values,
                            form: {
                                reset,
                                setErrors: setErrorsCallback,
                                setSubmitting,
                                setSubmitError: setSubmitErrorCallback,
                                validateAll,
                                setField,
                                setFieldError
                            }
                        };
                        
                        await onSubmit(context);
                        submissionSuccess = true;
                        
                        // Call onSubmitSuccess hook
                        if (submitLifecycle?.onSubmitSuccess) {
                            await submitLifecycle.onSubmitSuccess(values);
                        }
                    }
                } catch (error) {
                    console.error('Form submission error:', error);
                    submissionSuccess = false;
                    
                    // Set submit error for user feedback
                    const errorMessage = error instanceof Error ? error.message : 'Submission failed';
                    setSubmitError(errorMessage);
                    
                    // Call onSubmitError hook
                    if (submitLifecycle?.onSubmitError && error instanceof Error) {
                        await submitLifecycle.onSubmitError(error, values);
                    }
                } finally {
                    // Ensure submitting state is always reset
                    setIsSubmitting(false);
                    
                    // Call onSubmitComplete hook
                    if (submitLifecycle?.onSubmitComplete) {
                        await submitLifecycle.onSubmitComplete(values, submissionSuccess);
                    }
                }
            };
        },
        [values, validateAll, validationLifecycle, submitLifecycle, canSubmit, isSubmitting, reset, setErrorsCallback, setSubmitting, setSubmitErrorCallback, setField, setFieldError]
    );

    /**
     * Form hook return object providing state and handlers for the form.
     * @property values - Current form field values.
     * @property errors - Validation errors for each field.
     * @property touched - Flags indicating which fields have been visited.
     * @property dirty - Boolean flag indicating if any field value has changed from its initial value.
     * @property isSubmitting - Indicates whether the form is currently being submitted.
     * @property submitError - Error message from a failed form submission.
     * @property validationState - Overall validation state (e.g., pending, completed).
     * @property formError - General form error not tied to a specific field.
     * @property handleChange - Handler to update field values on input change.
     * @property handleBlur - Handler to mark a field as touched on blur.
     * @property setField - Manually set a specific field value.
     * @property setFieldError - Manually set a specific field error.
     * @property setErrors - Callback to set multiple field errors at once.
     * @property setSubmitting - Manually control the submitting state.
     * @property setSubmitError - Manually set the submit error message.
     * @property reset - Reset the form to its initial state.
     * @property validateAll - Synchronously validate all fields.
     * @property validateFieldAsync - Asynchronously validate a single field.
     * @property validateAllAsync - Asynchronously validate all fields.
     * @property handleSubmit - Function to be used as form submit handler.
     * @property isValid - Boolean indicating if the form has no validation errors.
     * @property canSubmit - Boolean indicating if the form is ready to be submitted (valid and not submitting).
     * @property isDirty - Alias for `dirty`, indicates if form values have been modified.
     * @property isComplete - Boolean indicating if all required fields are filled.
     * @property submitCount - Number of times the form has been submitted.
     */
    return {
        values,
        errors,
        touched,
        dirty,
        isSubmitting,
        submitError,
        validationState,
        formError,
        handleChange,
        handleBlur,
        setField,
        setFieldError,
        setErrors: setErrorsCallback,
        setSubmitting,
        setSubmitError: setSubmitErrorCallback,
        reset,
        validateAll,
        validateFieldAsync,
        validateAllAsync,
        handleSubmit,
        isValid,
        canSubmit,
        isDirty,
        isComplete,
        submitCount
    };
}
