import React from 'react';
import { useForm } from '../hooks';
import type { FormProps } from '../types';

export function Form<T extends Record<string, any>>({
    initialValues,
    validationRules,
    validationLifecycle,
    formLevelValidation,
    submitLifecycle,
    onSubmit,
    children,
    className = '',
    id
}: FormProps<T>) {
    const form = useForm<T>(
        initialValues, 
        validationRules, 
        validationLifecycle, 
        formLevelValidation, 
        submitLifecycle
    );
    const { handleSubmit } = form;

    return (
        <form
            id={id}
            className={className}
            onSubmit={handleSubmit(onSubmit)}
            noValidate
        >
            {children(form)}
        </form>
    );
}
