import { PATTERNS } from "../constants/patterns";
import { DEFAULT_MESSAGES } from "../constants/messages";
import type { ValidationRule, StringValidationRule, NumberValidationRule, BooleanValidationRule, CommonValidationRule } from "../types";

/**
 * Predefined validation rules with strict typing
 */
export const RULES = {
    required: <T>(message?: string): ValidationRule<T> => ({
        required: true,
        message: message || DEFAULT_MESSAGES.required('Field'),
        custom: undefined,
    } as ValidationRule<T>),

    email: (message?: string): StringValidationRule => ({
        pattern: PATTERNS.EMAIL,
        message: message || DEFAULT_MESSAGES.email(),
    }),

    url: (message?: string): StringValidationRule => ({
        pattern: PATTERNS.URL,
        message: message || DEFAULT_MESSAGES.url(),
    }),

    minLength: (min: number, message?: string): StringValidationRule => ({
        min,
        message: message || DEFAULT_MESSAGES.minLength('Field', min),
    }),

    maxLength: (max: number, message?: string): StringValidationRule => ({
        max,
        message: message || DEFAULT_MESSAGES.maxLength('Field', max),
    }),

    min: (min: number, message?: string): NumberValidationRule => ({
        min,
        message: message || DEFAULT_MESSAGES.min('Field', min),
    }),

    max: (max: number, message?: string): NumberValidationRule => ({
        max,
        message: message || DEFAULT_MESSAGES.max('Field', max),
    }),

    pattern: (pattern: RegExp, message?: string): StringValidationRule => ({
        pattern,
        message: message || DEFAULT_MESSAGES.pattern('Field'),
    }),

    phone: (message?: string): StringValidationRule => ({
        pattern: PATTERNS.PHONE,
        message: message || 'Please enter a valid phone number',
    }),

    alphanumeric: (message?: string): StringValidationRule => ({
        pattern: PATTERNS.ALPHANUMERIC,
        message: message || 'Only alphanumeric characters are allowed',
    }),

    strongPassword: (message?: string): StringValidationRule => ({
        pattern: PATTERNS.STRONG_PASSWORD,
        message: message || 'Password must be at least 8 characters with uppercase, lowercase, and number',
    }),

    boolean: (message?: string): BooleanValidationRule => ({
        required: true,
        message: message || 'This field is required',
    }),
} as const;

/**
 * Combine multiple rules with union type inference
 * Implements sequential/short-circuit validation with priority order:
 * 1. Required validation
 * 2. Type-specific validation (min/max/pattern)
 * 3. Custom validation
 * 4. Cross-field validation
 * 5. Async validation (handled separately)
 */
export function combineRules<T>(...rules: ValidationRule<T>[]): ValidationRule<T> {
    const combined: ValidationRule<T> = {
        custom: (value: any, formValues?: any) => {
            // Step 1: Required validation (highest priority)
            for (const rule of rules) {
                if (
                    rule.required &&
                    (
                        value === null ||
                        value === undefined ||
                        (typeof value === 'string' && value.trim() === '')
                    )
                ) {
                    return rule.message || 'This field is required';
                }
            }

            // Step 2: Type-specific validation
            if (typeof value === 'string') {
                for (const rule of rules) {
                    if (rule.min && value.length < rule.min) {
                        return rule.message || `Must be at least ${rule.min} characters`;
                    }
                    if (rule.max && value.length > rule.max) {
                        return rule.message || `Must be no more than ${rule.max} characters`;
                    }
                    if (rule.pattern && !rule.pattern.test(value)) {
                        return rule.message || 'Format is invalid';
                    }
                }
            }

            if (typeof value === 'number') {
                for (const rule of rules) {
                    if (rule.min !== undefined && value < rule.min) {
                        return rule.message || `Must be at least ${rule.min}`;
                    }
                    if (rule.max !== undefined && value > rule.max) {
                        return rule.message || `Must be no more than ${rule.max}`;
                    }
                }
            }

            // Step 3: Custom validation
            for (const rule of rules) {
                if (rule.custom) {
                    const customErr = rule.custom(value, formValues);
                    if (customErr) return customErr;
                }
            }

            // Step 4: Cross-field validation (only if formValues provided)
            if (formValues) {
                for (const rule of rules) {
                    if (rule.crossField) {
                        const crossFieldErr = rule.crossField(value, formValues);
                        if (crossFieldErr) return crossFieldErr;
                    }
                }
            }

            return undefined;
        },
        // Combine async rules for separate async validation
        async: async (value: any, formValues?: any) => {
            for (const rule of rules) {
                if (rule.async) {
                    const asyncErr = await rule.async(value, formValues);
                    if (asyncErr) return asyncErr;
                }
            }
            return undefined;
        }
    } as ValidationRule<T>;
    return combined;
}

/**
 * Type-safe rule combiner for specific field types
 */
export function combineStringRules(...rules: StringValidationRule[]): StringValidationRule {
    return rules.reduce((acc, rule) => ({ ...acc, ...rule }), {} as StringValidationRule);
}

export function combineNumberRules(...rules: NumberValidationRule[]): NumberValidationRule {
    return rules.reduce((acc, rule) => ({ ...acc, ...rule }), {} as NumberValidationRule);
}

export function combineBooleanRules(...rules: BooleanValidationRule[]): BooleanValidationRule {
    return rules.reduce((acc, rule) => ({ ...acc, ...rule }), {} as BooleanValidationRule);
}

/**
 * Create a custom rule with type inference
 */
export function createRule<T>(rule: ValidationRule<T>): ValidationRule<T> {
    return rule;
}

/**
 * Conditional rule builder
 */
export function when<T>(condition: boolean, rule: ValidationRule<T>): ValidationRule<T> {
    return condition ? rule : {} as ValidationRule<T>;
}
