// Common validation patterns
export const PATTERNS = {
    // Email pattern
    EMAIL: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
    
    // URL pattern
    URL: /^(https?:\/\/)?([\da-z.-]+)\.([a-z.]{2,6})([/\w .-]*)*\/?$/,
    
    // Phone number pattern (international)
    PHONE: /^[\+]?[(]?[0-9]{3}[)]?[-\s\.]?[0-9]{3}[-\s\.]?[0-9]{4,6}$/,
    
    // Alphanumeric only
    ALPHANUMERIC: /^[a-zA-Z0-9]+$/,
    
    // Letters only
    LETTERS_ONLY: /^[a-zA-Z]+$/,
    
    // Numbers only
    NUMBERS_ONLY: /^[0-9]+$/,
    
    // Strong password (min 8 chars, at least 1 uppercase, 1 lowercase, 1 number)
    STRONG_PASSWORD: /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)[a-zA-Z\d\w\W]{8,}$/,
} as const;
