import React, { createContext, useContext, ReactNode } from 'react';
import type { UseFormReturn } from '../types';

// Create the form context
const FormContext = createContext<UseFormReturn<any> | null>(null);

/**
 * Provider component for form context
 */
export function FormProvider<T extends Record<string, any>>({
    children,
    value,
}: {
    children: ReactNode;
    value: UseFormReturn<T>;
}) {
    return (
        <FormContext.Provider value={value}>
            {children}
        </FormContext.Provider>
    );
}

/**
 * Hook to use form context
 */
export function useFormContext<T extends Record<string, any>>(): UseFormReturn<T> {
    const context = useContext(FormContext);
    if (!context) {
        throw new Error('useFormContext must be used within a FormProvider');
    }
    return context as UseFormReturn<T>;
}
